const savedLang = () => { try { return localStorage.getItem("vault-watch-lang"); } catch { return null; } };
export let lang = TEXTS[savedLang()] ? savedLang() : (navigator.language || "en").startsWith("fr") ? "fr" : "en";
export let T = TEXTS[lang];
// Another language chosen (the toggle of the header): the texts follow
export function setLang(l) { lang = l; T = TEXTS[lang]; }
// The texts of the other modules under their key, in both languages: T.settings (settings.js), T.theme (themes.js),
// T.notify (notify.js), T.feedback (feedback.js); each module adds its own as it loads
export function addTexts(key, texts) { for (const l of ["fr", "en"]) TEXTS[l][key] = texts[l]; }
// A size in KB (« Ko » in French), one decimal under 10
export const kb = n => `${(n / 1024).toLocaleString(lang, { maximumFractionDigits: Math.abs(n) < 10240 ? 1 : 0 })} ${lang === "fr" ? "Ko" : "KB"}`;
export const signedKb = n => `${n > 0 ? "+" : ""}${kb(n)}`;
